"""Operator algebra on O(x)O generated by theta_1, theta_2, D_1, D_2 (Koszul signs), normal order
theta_1^e1 theta_2^e2 D_1^i D_2^j.  Defect of P = sum c_ij D_1^i D_2^j under K_{t theta}; after the
multiplication m, theta_2 at the left becomes theta_1 and theta_1 theta_2 becomes 0.
Result: block equations as coefficients of m(theta^eps D_1^i D_2^j)."""
import sympy as sp
from collections import defaultdict
a, b, c = sp.symbols('a b c')

def lmul_gen(g, el):
    out = defaultdict(lambda: 0)
    for (e1, e2, i, j), v in el.items():
        if g == 't1':
            if not e1: out[(1, e2, i, j)] += v
        elif g == 't2':
            if not e2: out[(e1, 1, i, j)] += (-1)**e1 * v
        elif g == 'D2':
            s = (-1)**e1
            if not e2: out[(e1, 0, i, j+1)] += s*(-1)**i*v
            else:
                out[(e1, 0, i, j)] += s*v
                out[(e1, 1, i, j+1)] += -s*(-1)**i*v
        elif g == 'D1':
            if not e1: out[(0, e2, i+1, j)] += (-1)**e2*v
            else:
                out[(0, e2, i, j)] += v
                out[(1, e2, i+1, j)] += -(-1)**e2*v
    return {k: sp.expand(v) for k, v in out.items() if sp.expand(v) != 0}

def mono_word(m):
    e1, e2, i, j = m
    return ['t1']*e1 + ['t2']*e2 + ['D1']*i + ['D2']*j

def mul(X, Y):
    out = defaultdict(lambda: 0)
    for m, v in X.items():
        el = dict(Y)
        for g in reversed(mono_word(m)):
            el = lmul_gen(g, el)
        for k, w in el.items(): out[k] += v*w
    return {k: sp.expand(v) for k, v in out.items() if sp.expand(v) != 0}

def add(*Xs, coef=None):
    out = defaultdict(lambda: 0); coef = coef or [1]*len(Xs)
    for cf, X in zip(coef, Xs):
        for k, v in X.items(): out[k] += cf*v
    return {k: sp.expand(v) for k, v in out.items() if sp.expand(v) != 0}

M = lambda e1, e2, i, j: {(e1, e2, i, j): 1}
T1, T2, D1, D2, ONE = M(1, 0, 0, 0), M(0, 1, 0, 0), M(0, 0, 1, 0), M(0, 0, 0, 1), M(0, 0, 0, 0)
K1 = add(mul(T1, M(0, 0, 2, 0)), D1, coef=[2, -1])        # K = 2 theta D^2 - D
K2 = add(mul(T2, M(0, 0, 0, 2)), D2, coef=[2, -1])

def comm_t1(i, j):    # [t_1, D_1^i D_2^j]
    r = {}
    if i >= 2: r = add(r, M(0, 0, i-2, j), coef=[1, -(i//2)])
    if i % 2: r = add(r, M(1, 0, i-1, j), coef=[1, -1])
    return r
def comm_t2(i, j):    # [t_2, D_1^i D_2^j] = -D_1^i [D^j,t]_2
    r = {}
    if j >= 2: r = add(r, M(0, 0, i, j-2), coef=[1, -(j//2)])
    if j % 2: r = add(r, mul(M(0, 0, i, 0), mul(T2, M(0, 0, 0, j-1))), coef=[1, -1])
    return r

def defect(i, j):
    pi = (i+j) % 2; s = (-1)**pi; P = M(0, 0, i, j)
    return add(mul(comm_t1(i, j), K1), mul(comm_t2(i, j), K2), mul(T1, P), mul(P, T1), mul(P, T2),
               coef=[s, s, c, -s*a, -s*b])

def apply_m(X):
    out = defaultdict(lambda: 0)
    for (e1, e2, i, j), v in X.items():
        if e1 and e2: continue
        out[(e1 or e2, i, j)] += v
    return {k: sp.expand(v) for k, v in out.items() if sp.expand(v) != 0}

if __name__ == "__main__":
    # sanity: (K1+K2) P = (-1)^pi P (K1+K2)
    Ks = add(K1, K2)
    for i in range(4):
        for j in range(4):
            P = M(0, 0, i, j); s = (-1)**((i+j) % 2)
            assert add(mul(Ks, P), mul(P, Ks), coef=[1, -s]) == {}, (i, j)
    print("K_theta supercommutes with D_1^i D_2^j: OK")
    for i in range(4):
        for j in range(4):
            print((i, j), apply_m(defect(i, j)))
